describe('Error Message Announcements for Screen Readers', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should announce error messages when form validation fails', () => {
    // Attempt to submit form with invalid email
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="email-error-message"]').should('contain', 'Please enter a valid email address');

    // Verify error message is announced by screen reader
    cy.get('[data-testid="email-error-message"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="email-error-message"]').should('have.attr', 'role', 'alert');

    // Verify focus is managed correctly
    cy.get('[data-testid="email-input"]').should('have.focus');
  });

  it('should announce multiple error messages when multiple fields are invalid', () => {
    // Fill form with multiple invalid fields
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="password-input"]').type('short');
    cy.get('[data-testid="confirm-password-input"]').type('different');
    cy.get('[data-testid="submit-button"]').click();

    // Verify all error messages appear
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="password-error-message"]').should('be.visible');
    cy.get('[data-testid="confirm-password-error-message"]').should('be.visible');

    // Verify all error messages are announced by screen reader
    cy.get('[data-testid="email-error-message"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="password-error-message"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="confirm-password-error-message"]').should('have.attr', 'aria-live', 'polite');

    // Verify focus is managed to the first error
    cy.get('[data-testid="email-input"]').should('have.focus');
  });
});
